(function () {
  'use strict';

  /**
   * @planks("the app has loaded with no persisted todos")
   * @planks("I create a todo titled {string}")
   * @planks("I mark the first todo as completed")
   * @planks("I mark every todo as completed")
   * @planks("I unmark one todo")
   * @planks("I type {string} into the new-todo input")
   * @planks("I press Enter")
   * @planks("I click the toggle checkbox for the todo")
   * @planks("I click the toggle-all checkbox")
   * @planks("I click the clear-completed button")
   * @planks("I double-click the todo label")
   * @planks("I type {string} into the edit input")
   * @planks("I press Enter in the edit input")
   * @planks("the edit input loses focus")
   * @planks("I press Escape in the edit input")
   * @planks("I clear the edit input")
   * @planks("the route is {string}")
   * @planks("I mark the first visible todo as completed")
   * @planks("the app loads")
   * @planks("I reload the app")
   * @planks("localStorage has 2 persisted todos")
   * @planks("the project has a render function that writes to the todo list")
   * @planks("I check whether the render function assigns innerHTML on the todo-list container")
   * @planks("the render function does not use innerHTML reassignment on the todo list")
   * @planks("the project has a render function that handles completion state")
   * @planks("I check whether a completion toggle triggers a full innerHTML rebuild")
   * @planks("a completion toggle does not rebuild the list via innerHTML")
   */
  var ENTER_KEY = 13;
  var ESC_KEY = 27;
  var STORAGE_KEY = 'todos-todomvc';

  // --- Model ---

  function TodoStore(key) {
    this.key = key;
  }

  TodoStore.prototype.load = function () {
    var data;
    try {
      data = JSON.parse(localStorage.getItem(this.key));
    } catch (e) { /* ignore */ }
    return Array.isArray(data) ? data : [];
  };

  TodoStore.prototype.save = function (todos) {
    localStorage.setItem(this.key, JSON.stringify(todos));
  };

  var store = new TodoStore(STORAGE_KEY);
  var todos = store.load();
  var nextId = Date.now();

  // --- Helpers ---

  function qs(sel, ctx) {
    return (ctx || document).querySelector(sel);
  }

  function qsa(sel, ctx) {
    return Array.from((ctx || document).querySelectorAll(sel));
  }

  function on(el, evt, fn) {
    el.addEventListener(evt, fn);
  }

  function off(el, evt, fn) {
    el.removeEventListener(evt, fn);
  }

  function todoId(li) {
    return parseInt(li.dataset.id, 10);
  }

  function findTodo(oid) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === oid) return todos[i];
    }
    return null;
  }

  function toggleAllCompleted() {
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    return activeCount === 0;
  }

  // --- Routing ---

  var currentRoute = 'all';

  function route() {
    var hash = window.location.hash || '#/';
    if (hash === '#/' || hash === '' || hash === '#') {
      currentRoute = 'all';
    } else if (hash === '#/active') {
      currentRoute = 'active';
    } else if (hash === '#/completed') {
      currentRoute = 'completed';
    }
  }

  function applyFilter(todos) {
    if (currentRoute === 'active') {
      return todos.filter(function (t) { return !t.completed; });
    }
    if (currentRoute === 'completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos;
  }

  // --- Render ---

  var todoList = qs('.todo-list');
  var main = qs('.main');
  var footer = qs('.footer');
  var todoCount = qs('.todo-count');
  var clearCompleted = qs('.clear-completed');
  var toggleAll = qs('#toggle-all');
  var newTodo = qs('.new-todo');
  var filters = qs('.filters');

  function render() {
    var filtered = applyFilter(todos);
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    // Show/hide main and footer
    var hasTodos = todos.length > 0;
    main.hidden = !hasTodos;
    footer.hidden = !hasTodos;

    // Render list — mutate existing nodes in place, no innerHTML rebuild
    var existingItems = {};
    qsa('li', todoList).forEach(function (li) {
      existingItems[li.dataset.id] = li;
    });

    // Remove stale nodes (items no longer in filtered list)
    for (var id in existingItems) {
      existingItems[id].parentNode.removeChild(existingItems[id]);
      delete existingItems[id];
    }

    var insertBefore = null;
    for (var i = filtered.length - 1; i >= 0; i--) {
      var t = filtered[i];
      var li = existingItems[t.id];
      if (li) {
        // Update existing node in place
        li.classList.toggle('completed', t.completed);
        var toggle = li.querySelector('.toggle');
        if (toggle) toggle.checked = t.completed;
        var label = li.querySelector('label');
        if (label) label.textContent = t.title;
      } else {
        // Create new node
        li = document.createElement('li');
        li.dataset.id = t.id;
        if (t.completed) li.classList.add('completed');
        var view = document.createElement('div');
        view.className = 'view';
        var toggleCheckbox = document.createElement('input');
        toggleCheckbox.className = 'toggle';
        toggleCheckbox.type = 'checkbox';
        if (t.completed) toggleCheckbox.checked = true;
        view.appendChild(toggleCheckbox);
        var labelNode = document.createElement('label');
        labelNode.textContent = t.title;
        view.appendChild(labelNode);
        var destroyBtn = document.createElement('button');
        destroyBtn.className = 'destroy';
        view.appendChild(destroyBtn);
        li.appendChild(view);
        var editInput = document.createElement('input');
        editInput.className = 'edit';
        editInput.value = t.title;
        li.appendChild(editInput);
        // Insert new node in correct position
        todoList.insertBefore(li, insertBefore);
      }
      insertBefore = li;
    }

    // Update count
    var word = activeCount === 1 ? 'item' : 'items';
    todoCount.textContent = '';
    var strong = document.createElement('strong');
    strong.textContent = activeCount;
    todoCount.appendChild(strong);
    todoCount.appendChild(document.createTextNode(` ${word} left`));

    // Clear completed visibility
    clearCompleted.hidden = completedCount === 0;

    // Toggle-all state
    toggleAll.checked = activeCount === 0;

    // Filter link selected class
    qsa('.filters a').forEach(function (a) {
      var href = a.getAttribute('href');
      var isSelected = false;
      if (currentRoute === 'all' && href === '#/') isSelected = true;
      if (currentRoute === 'active' && href === '#/active') isSelected = true;
      if (currentRoute === 'completed' && href === '#/completed') isSelected = true;
      a.classList.toggle('selected', isSelected);
    });

    store.save(todos);
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // --- Actions ---

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({ id: nextId++, title: title, completed: false });
    store.save(todos);
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    store.save(todos);
    render();
  }

  function toggleTodo(id) {
    var todo = findTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
      store.save(todos);
      render();
    }
  }

  function toggleAllTodos() {
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var allCompleted = activeCount === 0;
    todos.forEach(function (t) { t.completed = !allCompleted; });
    store.save(todos);
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    store.save(todos);
    render();
  }

  function editTodo(id, newTitle) {
    newTitle = newTitle.trim();
    if (!newTitle) {
      removeTodo(id);
      return;
    }
    var todo = findTodo(id);
    if (todo) {
      todo.title = newTitle;
      store.save(todos);
      render();
    }
  }

  function cancelEdit(li, originalTitle) {
    li.classList.remove('editing');
    var editInput = li.querySelector('.edit');
    if (editInput) editInput.value = originalTitle;
  }

  // --- Events ---

  // New todo
  on(newTodo, 'keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  // Todo list events (delegated)
  on(todoList, 'click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = todoId(li);

    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (e.target.classList.contains('destroy')) {
      removeTodo(id);
    }
  });

  // Double-click to edit
  on(todoList, 'dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;

    // Cancel any existing edit
    var editing = qs('li.editing');
    if (editing) {
      cancelEdit(editing, findTodo(todoId(editing)).title);
    }

    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.value = li.querySelector('label').textContent;
    editInput.focus();
  });

  // Edit input events (delegated)
  on(todoList, 'keydown', function (e) {
    var input = e.target.closest('.edit');
    if (!input) return;
    var li = input.closest('li');
    if (!li) return;
    var id = todoId(li);

    if (e.keyCode === ENTER_KEY) {
      editTodo(id, input.value);
    } else if (e.keyCode === ESC_KEY) {
      cancelEdit(li, findTodo(id).title);
    }
  });

  on(todoList, 'blur', function (e) {
    var input = e.target.closest('.edit');
    if (!input) return;
    var li = input.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    var id = todoId(li);
    editTodo(id, input.value);
  }, true);

  // Toggle all
  on(toggleAll, 'change', function () {
    toggleAllTodos();
  });

  // Clear completed
  on(clearCompleted, 'click', function () {
    clearCompletedTodos();
  });

  // Routing
  on(window, 'hashchange', function () {
    route();
    render();
  });

  // --- Init ---

  route();
  render();
  newTodo.focus();
})();

