When('I check whether the render function creates new list-item elements for items that already exist', function () {
  const source = this.appSource;
  // Detect the anti-pattern where the render function NEVER checks whether a DOM
  // element already exists for a given todo item before creating a new <li>.
  // In a correct implementation, the render function looks up existing items
