  // by the earlier check) and never actually reuses them — so the reuse branch
  // `if (li) { ... update in place ... }` is dead code.
  const hasLookupPattern = /existingItems\[[^\]]+\]/.test(source);
  const hasReuseAttempt = /if\s*\(\s*li\s*\)/.test(source);
  const hasCreateLi = /createElement\s*\(\s*['"]li['"]\s*\)/.test(source);
